package test;

import org.eclipse.jface.action.IMenuListener;
import org.eclipse.jface.action.MenuManager;

public class NegativeExample {
    private MenuManager fMenuManager = new MenuManager();

    public void setup() {
        // Lambda with block body
        fMenuManager.addMenuListener(m -> {
            System.out.println("Processing " + m);
            contextMenuAboutToShow(m);
        });
        // Lambda with modified argument
        fMenuManager.addMenuListener(m -> contextMenuAboutToShow(m == null ? null : m));
        // Lambda calling a method without matching parameter
        fMenuManager.addMenuListener(m -> anotherMethod());
    }

    private void contextMenuAboutToShow(IMenuManager menuManager) { /*...*/ }
    private void anotherMethod() { /*...*/ }
}
